            0x41, 0x42, 0x50, 0x51, 0x52, 0x53, 0x54, 0x55, 0x56, 0x57,
            0x58, 0x59, 0x5a, 0x5b, 0x5c, 0x5d, 0x5e, 0x91, 0x92, 0x93,
            0x59, 0x5a, 0x5c, 0x5c, 0x60, 0x61, 0x62, 0x64, 0x80, 0x81,
